package kr.minecraft.survival.civic;

import java.util.*;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataType;
import kr.minecraft.survival.economy.domain.*;

/** Slot actions are server-owned; no action is read from a player's item metadata. */
final class CivicMenus implements Listener {
    static final int[] CELLS={10,11,12,13,14,15,16,19,20,21,22,23,24,25,28,29,30,31,32,33,34,37,38,39,40,41,42,43};
    static final class Screen implements InventoryHolder {
        final UUID owner;final Inventory inventory;final Map<Integer,Runnable> actions=new HashMap<>();
        Screen(KoreanCivicPlugin plugin,Player p,String title){owner=p.getUniqueId();inventory=plugin.getServer().createInventory(this,54,title);}
        public Inventory getInventory(){return inventory;}
    }
    final KoreanCivicPlugin p;
    CivicMenus(KoreanCivicPlugin plugin){p=plugin;}
    static ItemStack icon(Material material,String name,String model,String... lines){ItemStack item=new ItemStack(material);ItemMeta meta=item.getItemMeta();meta.setDisplayName(name);meta.setLore(List.of(lines));if(model!=null)meta.getPersistentDataContainer().set(new NamespacedKey("tycoon","ui_icon"),PersistentDataType.STRING,model);item.setItemMeta(meta);return item;}
    Screen screen(Player player,String title,Runnable back){Screen s=new Screen(p,player,title);ItemStack border=icon(Material.GRAY_STAINED_GLASS_PANE," ",null);for(int slot=0;slot<54;slot++)s.inventory.setItem(slot,border);button(s,45,Material.ARROW,"§e뒤로","ui/back",back);button(s,49,Material.BARRIER,"§c닫기","close",player::closeInventory);return s;}
    void button(Screen s,int slot,Material material,String name,String model,Runnable action,String... lines){s.inventory.setItem(slot,icon(material,name,model,lines));if(action!=null)s.actions.put(slot,action);}
    void show(Player player,Screen s){player.openInventory(s.inventory);}
    void main(Player player){var menu=p.getServer().getPluginManager().getPlugin("KoreanMenu");if(menu!=null&&menu.isEnabled())try{menu.getClass().getMethod("openFromNavigation",Player.class).invoke(menu,player);return;}catch(ReflectiveOperationException e){p.getLogger().warning("메인 메뉴 연동 실패: "+e);}player.closeInventory();}
    void confirm(Player player,String title,ItemStack preview,String[] details,Runnable action,Runnable back){Screen s=screen(player,title,back);s.inventory.setItem(22,preview.clone());button(s,4,Material.BOOK,"§e거래 내용을 확인하세요","business_ledger",null,details);button(s,30,Material.LIME_CONCRETE,"§a확인 · 거래 진행","confirm",action,"§7왼쪽 클릭 한 번으로 확정합니다.");button(s,32,Material.RED_CONCRETE,"§c취소","close",back);show(player,s);}
    void town(Player player){Screen s=screen(player,"마을 | 설립·필지 매매",()->main(player));var mine=p.store.founded(player.getUniqueId());Location at=player.getLocation();button(s,4,Material.MAP,"§6마을·땅 거래","land_deed",null,"§7필지 1개 = 16×16, 모든 높이","§7현재 청크: "+(at.getBlockX()>>4)+", "+(at.getBlockZ()>>4),"§7F3+G로 청크 경계를 확인하세요.");button(s,10,Material.OAK_SAPLING,"§a마을 설립","city_spawn",()->founding(player,p.defaultName(player)),"§7첫 필지 포함 · "+Money.display(p.founding),"§7한 사람당 설립 마을 1개","§7기본 이름: "+p.defaultName(player),"§7이름 지정: /마을 설립 이름");button(s,12,Material.GOLDEN_SHOVEL,"§b현재 청크로 영역 확장","land_deed",()->expansion(player),"§7마을 설립자만 확장 가능","§7한 변이 맞닿은 필지 · "+Money.display(p.expansion),"§7마을당 최대 "+p.maxPlots+"필지");button(s,14,Material.WRITABLE_BOOK,"§e내 필지 · 판매 관리","business_ledger",()->plots(player,"내것",0),"§7분양 가격 설정 · 판매 취소","§7구매한 땅도 다시 판매할 수 있습니다.");button(s,16,Material.EMERALD,"§a분양·판매 중인 필지","transfer",()->plots(player,"판매",0),"§7가격·위치·소유자를 확인하고 구매");if(mine!=null)button(s,22,Material.FILLED_MAP,"§6"+mine.name(),"land_deed",()->plots(player,mine.id(),0),"§7내가 설립한 마을의 전체 필지","§7등록 필지 "+p.store.plots().stream().filter(v->v.town().equals(mine.id())).count()+" / "+p.maxPlots);button(s,24,Material.CHEST,"§6개인상점","seller_crate",()->market(player,false,0));button(s,40,Material.GOLD_INGOT,"§e판매대금 받기","wallet",()->collection(player),"§7필지·물품 판매 적립: "+Money.display(p.store.credit(player.getUniqueId())));show(player,s);}
    void founding(Player player,String name){Location l=player.getLocation();String w=l.getWorld().getUID().toString();int x=l.getBlockX()>>4,z=l.getBlockZ()>>4;confirm(player,"마을 | 설립 확인",icon(Material.OAK_SAPLING,"§a"+name,"city_spawn"),new String[]{"§f설립비: "+Money.display(p.founding),"§f첫 필지: "+l.getWorld().getName()+" 청크 "+x+", "+z,"§7현재 청크에서 확정하세요. 건물은 직접 건축합니다."},()->{p.found(player,name,w,x,z);town(player);},()->town(player));}
    void expansion(Player player){var town=p.store.founded(player.getUniqueId());if(town==null)throw new StateStore.Denied("먼저 마을을 설립하세요.");Location l=player.getLocation();String w=l.getWorld().getUID().toString();int x=l.getBlockX()>>4,z=l.getBlockZ()>>4;confirm(player,"마을 | 영역 확장 확인",icon(Material.GOLDEN_SHOVEL,"§b"+town.name()+" 영역 확장","land_deed"),new String[]{"§f확장비: "+Money.display(p.expansion),"§f선택 필지: "+l.getWorld().getName()+" 청크 "+x+", "+z,"§7기존 마을과 한 변이 맞닿아야 합니다."},()->{p.expand(player,town.id(),w,x,z);town(player);},()->town(player));}
    void plots(Player player,String filter,int requested){List<CivicStore.Plot> all=p.store.plots().stream().filter(v->v.state().equals("ACTIVE")).filter(v->filter.equals("내것")?v.owner().equals(player.getUniqueId().toString()):filter.equals("판매")?v.price()>0:v.town().equals(filter)).toList();int page=Math.max(0,Math.min(requested,Math.max(0,(all.size()-1)/28)));Screen s=screen(player,"필지 | "+(filter.equals("내것")?"내 필지":filter.equals("판매")?"분양·판매":"마을 전체")+" "+(page+1),()->town(player));button(s,4,Material.MAP,"§6필지 "+all.size()+"개 · "+(page+1)+" / "+Math.max(1,(all.size()+27)/28),"land_deed",null,"§7소유자·위치·묶음 가격을 확인하세요.");for(int i=page*28;i<Math.min(all.size(),page*28+28);i++){var plot=all.get(i);var t=p.store.town(plot.town());String location=p.world(plot.world()).getName()+" 청크 "+plot.x()+", "+plot.z();button(s,CELLS[i-page*28],Material.FILLED_MAP,"§e"+t.name()+" · 필지","land_deed",()->plot(player,plot.id()),"§7소유자: "+p.owner(plot.owner()),"§7"+location,"§7블록 X "+plot.x()*16+"~"+(plot.x()*16+15)+" / Z "+plot.z()*16+"~"+(plot.z()*16+15),plot.price()>0?"§a판매가: "+Money.display(plot.price()):"§7판매 중 아님","§e왼쪽 클릭: 상세·구매·판매 관리");}if(all.isEmpty())button(s,22,Material.PAPER,"§7표시할 필지가 없습니다","ui/missing",null);if(page>0)button(s,48,Material.ARROW,"§e이전 페이지","ui/back",()->plots(player,filter,page-1));if((page+1)*28<all.size())button(s,50,Material.ARROW,"§e다음 페이지","ui/ready",()->plots(player,filter,page+1));show(player,s);}
    void plot(Player player,String id){var plot=p.store.plot(id);if(!plot.state().equals("ACTIVE"))throw new StateStore.Denied("거래 확인 중인 필지입니다.");if(plot.owner().equals(player.getUniqueId().toString())){plotEditor(player,id,plot.price()>0?plot.price():Math.min(100000,p.maxPrice));return;}if(plot.price()<1)throw new StateStore.Denied("현재 판매 중인 필지가 아닙니다.");long expected=plot.price();confirm(player,"필지 | 구매 확인",icon(Material.FILLED_MAP,"§e"+p.store.town(plot.town()).name(),"land_deed"),new String[]{"§f구매가: "+Money.display(expected),"§f판매자: "+p.owner(plot.owner()),"§f"+p.world(plot.world()).getName()+" 청크 "+plot.x()+", "+plot.z(),"§7매매 후 소유권이 이전됩니다. 가구·일반 건축물 포함."},()->{p.buyPlot(player,id,expected);plots(player,"내것",0);},()->plots(player,"판매",0));}
    void priceButtons(Screen s,long price,java.util.function.LongConsumer reopen){long[] steps={-100000,-10000,-1000,1000,10000,100000};int[] slots={10,11,12,14,15,16};for(int i=0;i<steps.length;i++){long step=steps[i],next=Math.max(100,Math.min(p.maxPrice,price+step));button(s,slots[i],step<0?Material.RED_DYE:Material.LIME_DYE,(step>0?"§a+":"§c-")+Money.display(Math.abs(step)),null,()->reopen.accept(next));}}
    void plotEditor(Player player,String id,long price){var plot=p.store.plot(id);if(!plot.owner().equals(player.getUniqueId().toString())||!plot.state().equals("ACTIVE"))throw new StateStore.Denied("내 소유 필지만 판매 관리할 수 있습니다.");Screen s=screen(player,"필지 | 분양·재판매 설정",()->plots(player,"내것",0));button(s,4,Material.MAP,"§6판매가: "+Money.display(price),"land_deed",null,"§7청크 "+plot.x()+", "+plot.z()+" 전체 가격","§7다른 이용자가 구매하면 소유권이 이전됩니다.","§7커스텀 농작물은 먼저 수확·회수하세요.");priceButtons(s,price,next->plotEditor(player,id,next));button(s,30,Material.LIME_CONCRETE,"§a판매 등록 확인","confirm",()->confirm(player,"필지 | 판매 등록 확인",icon(Material.MAP,"§e분양·재판매","land_deed"),new String[]{"§f가격: "+Money.display(price),"§f청크 "+plot.x()+", "+plot.z(),"§7판매 중에는 다른 이용자가 구매할 수 있습니다."},()->{p.sellPlot(player,id,price);plots(player,"내것",0);},()->plotEditor(player,id,price)));button(s,32,Material.RED_CONCRETE,"§c판매 취소","close",()->{p.sellPlot(player,id,0);plots(player,"내것",0);},"§7소유권은 유지하고 분양 목록에서 내립니다.");show(player,s);}
    void market(Player player,boolean mine,int requested){List<CivicStore.Listing> all=p.store.listings(mine?player.getUniqueId():null);int page=Math.max(0,Math.min(requested,Math.max(0,(all.size()-1)/28)));Screen s=screen(player,"개인상점 | "+(mine?"내 판매":"전체 물품")+" "+(page+1),()->main(player));button(s,4,Material.ENDER_CHEST,"§6개인상점 · "+all.size()+"건","seller_crate",null,"§7가격은 표시된 수량 전체의 가격입니다.","§7등록자 접속 여부와 관계없이 구매할 수 있습니다.");for(int i=page*28;i<Math.min(all.size(),page*28+28);i++){var row=all.get(i);ItemStack preview=p.escrow(row);ItemMeta meta=preview.getItemMeta();List<String> lore=new ArrayList<>(meta.hasLore()?meta.getLore():List.of());lore.addAll(List.of("§8────────────","§7판매자: "+p.owner(row.seller()),"§e"+row.amount()+"개 전체 "+Money.display(row.price()),row.seller().equals(player.getUniqueId().toString())?"§c왼쪽 클릭: 회수 확인":"§a왼쪽 클릭: 구매 확인"));meta.setLore(lore);preview.setItemMeta(meta);int slot=CELLS[i-page*28];s.inventory.setItem(slot,preview);s.actions.put(slot,()->item(player,row.id(),row.price()));}if(all.isEmpty())button(s,22,Material.PAPER,"§7등록된 물품이 없습니다","ui/missing",null,"§7손에 든 물품 등록 버튼을 눌러 시작하세요.");button(s,46,Material.CHEST,"§a손에 든 물품 등록","seller_crate",()->{ItemStack item=p.saleItem(player);listEditor(player,item,item.getAmount(),Math.min(10000,p.maxPrice));},"§7등록하면 물건을 보관합니다.","§7묶음 전체 가격을 정합니다.");button(s,47,Material.BOOK,mine?"§e전체 물품":"§e내 판매 관리","business_ledger",()->market(player,!mine,0));button(s,51,Material.GOLD_INGOT,"§e판매대금 받기","wallet",()->collection(player),"§7받을 금액: "+Money.display(p.store.credit(player.getUniqueId())));button(s,53,Material.CLOCK,"§b새로고침",null,()->market(player,mine,page));if(page>0)button(s,48,Material.ARROW,"§e이전 페이지","ui/back",()->market(player,mine,page-1));if((page+1)*28<all.size())button(s,50,Material.ARROW,"§e다음 페이지","ui/ready",()->market(player,mine,page+1));show(player,s);}
    void listEditor(Player player,ItemStack expected,int count,long price){Screen s=screen(player,"개인상점 | 물품 등록 설정",()->market(player,false,0));ItemStack preview=expected.clone();preview.setAmount(count);s.inventory.setItem(22,preview);button(s,4,Material.BOOK,"§e"+count+"개 전체 가격: "+Money.display(price),"business_ledger",null,"§7개당 가격이 아닌 선택한 묶음 전체 가격입니다.","§7가격 직접 지정: /개인상점 등록 가격 수량");priceButtons(s,price,next->listEditor(player,expected,count,next));button(s,28,Material.RED_DYE,"§c수량 -1",null,()->listEditor(player,expected,Math.max(1,count-1),price));button(s,34,Material.LIME_DYE,"§a수량 +1",null,()->listEditor(player,expected,Math.min(expected.getAmount(),count+1),price));button(s,40,Material.CHEST,"§e손에 든 수량 전부","seller_crate",()->listEditor(player,expected,expected.getAmount(),price));button(s,30,Material.LIME_CONCRETE,"§a판매 등록 확인","confirm",()->confirm(player,"개인상점 | 등록 확인",preview,new String[]{"§f수량: "+count+"개 / 묶음 전체 가격: "+Money.display(price),"§7물건을 가방에서 빼서 상점에 보관합니다.","§7팔리기 전에는 내 판매 관리에서 회수할 수 있습니다."},()->{p.list(player,expected,count,price);market(player,true,0);},()->listEditor(player,expected,count,price)));show(player,s);}
    void item(Player player,String id,long expected){var row=p.store.listing(id);if(!row.state().equals("ACTIVE")||row.price()!=expected)throw new StateStore.Denied("판매 상태가 바뀌었습니다. 새로고침하세요.");boolean cancel=row.seller().equals(player.getUniqueId().toString());confirm(player,cancel?"개인상점 | 물품 회수 확인":"개인상점 | 구매 확인",p.escrow(row),new String[]{"§f판매자: "+p.owner(row.seller()),"§f"+row.amount()+"개 전체 가격: "+Money.display(expected),cancel?"§7판매를 취소하고 원래 물건을 가방으로 돌려받습니다.":"§7확인하면 기존 지갑에서 돈을 지불하고 물건을 받습니다."},()->{p.buyItem(player,id,expected,cancel);market(player,cancel,0);},()->market(player,cancel,0));}
    void collection(Player player){long credit=p.store.credit(player.getUniqueId());confirm(player,"판매대금 | 받기 확인",icon(Material.GOLD_INGOT,"§e판매대금: "+Money.display(credit),"wallet"),new String[]{"§f필지·물품 판매 후 쌓인 금액입니다.","§f받을 금액: "+Money.display(credit),"§7확인 시 현재 적립된 판매대금 전액을 받습니다."},()->{p.collect(player);market(player,true,0);},()->market(player,true,0));}
    @EventHandler(priority=EventPriority.HIGHEST) public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof Screen s))return;e.setCancelled(true);if(e.getClick()!=ClickType.LEFT||!(e.getWhoClicked() instanceof Player player)||!s.owner.equals(player.getUniqueId()))return;Runnable action=s.actions.get(e.getRawSlot());if(action==null)return;p.getServer().getScheduler().runTask(p,()->{if(!player.isOnline()||player.getOpenInventory().getTopInventory()!=s.inventory)return;player.closeInventory();p.safe(player,()->{p.ready(player);action.run();});});}
    @EventHandler(priority=EventPriority.HIGHEST) public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof Screen)e.setCancelled(true);}
}
